#include <bits/stdc++.h>
using namespace std;

constexpr long long MOD=998244353;

vector<long long> modularinevrese(1,0);
vector<long long> harmonic(1,0);

void ensureharmonic(int n){
    int fistnew=static_cast<int>(harmonic.size());
    
    if(fistnew>n) return;
    
    modularinevrese.resize(n+1);
    harmonic.resize(n+1);
    
    for(int i=fistnew;i<=n;++i){
        if(i==1){
            modularinevrese[i]=1;
        }
        else{
            modularinevrese[i]= MOD-(MOD/i)*modularinevrese[MOD%i]%MOD;
        }
        harmonic[i]=(harmonic[i-1]+modularinevrese
        [i])%MOD;
    }
}

int main() {
	// your code goes here
	int t;
	cin>>t;
	while(t--){
	    int n;
	    cin>>n;
	    ensureharmonic(n);
	    
	    long long ans=0;
	    for(int i=0;i<n;++i){
	        long long value;
	        cin>>value;
	        
	        value%=MOD;
	        
	        long long exp = (harmonic[i]+harmonic[n-1-i])%MOD;
	        
	        ans=(ans+value*exp)%MOD;

	    }
	    cout<<ans<<'\n';
	}

}
